#!/usr/bin/env bash
set -euo pipefail
ROOT="${1:-.}"
ARCHIVE="$(mktemp /tmp/shadevpn.XXXXXX.zip)"
trap 'rm -f "$ARCHIVE"' EXIT
printf '%s' '' | base64 -d > "$ARCHIVE"
unzip -q "$ARCHIVE" -d "$ROOT/.shadevpn-bootstrap"
cp -R "$ROOT/.shadevpn-bootstrap/ShadeVPN-Android/." "$ROOT/"
rm -rf "$ROOT/.shadevpn-bootstrap"
echo 'Bootstrap installed successfully.'
